import { Suspense, useDeferredValue } from 'react';

import { PlottedLine } from './PlottedLine';
import { Axis } from './Axis';

const SpirographSvg = ({
  style,
  R,
  k,
  k2,
  h,
  glow,
  axis,
  strokeWidth,
  lines,
  width,
  height,
  maxRadius,
  background,
  foreground,
}) => {
  const deferredLines = useDeferredValue(lines);
  const deferredMaxRadius = useDeferredValue(maxRadius);
  const viewZoomRatio = (deferredMaxRadius * 2) / Math.min(width, height) || 1;

  return (
    <svg
      width={width}
      height={height}
      style={style}
      viewBox={`${-deferredMaxRadius} ${-deferredMaxRadius} ${deferredMaxRadius * 2} ${deferredMaxRadius * 2}`}
      id={'spirograph'}
    >
      <filter id={'glow'}>
        <feGaussianBlur result={'coloredBlur'} stdDeviation={glow} />
        <feMerge>
          <feMergeNode in={'coloredBlur'} />
          <feMergeNode in={'SourceGraphic'} />
        </feMerge>
      </filter>
      <defs>
        <linearGradient
          id={'lineGradient'}
          x1={0}
          x2={0}
          y1={-deferredMaxRadius}
          y2={deferredMaxRadius}
          gradientTransform={'rotate(24)'}
          gradientUnits={'userSpaceOnUse'}
        >
          <stop offset={0} stopColor={'#ffbc3b'} />
          <stop offset={0.15} stopColor={'#ffe26c'} />
          <stop offset={0.5} stopColor={'#fff3c0'} />
          <stop offset={0.85} stopColor={'#f589aa'} />
          <stop offset={1} stopColor={'#ff70ba'} />
        </linearGradient>
      </defs>

      <rect
        x={-width}
        y={-height}
        width={width * 2}
        height={height * 2}
        fill={background}
      />

      {deferredLines.map((line, i) => (
        <PlottedLine
          key={i}
          data={line}
          strokeWidth={strokeWidth * viewZoomRatio}
          filter={'url(#glow)'}
          stroke={'url(#lineGradient)'}
        />
      ))}
      {axis && (
        <Axis
          width={width}
          height={height}
          viewZoomRatio={viewZoomRatio}
          R={R}
          k={k}
          k2={k2}
          h={h}
          color={foreground}
        />
      )}
    </svg>
  );
};

export const Spirograph = (props) => {
  const { width, height, background, style } = props;

  return (
    <Suspense
      fallback={(
        <svg
          width={width}
          height={height}
          style={style}
          viewBox={`${-Math.max(1, width / 2)} ${-Math.max(1, height / 2)} ${Math.max(1, width)} ${Math.max(1, height)}`}
        >
          <rect
            x={-width}
            y={-height}
            width={width * 2}
            height={height * 2}
            fill={background}
          />
        </svg>
      )}
    >
      <SpirographSvg {...props} />
    </Suspense>
  );
};
